const msg = $('Telegram Update').first().json.message || {};
const row = $input.first().json || {};
const FIELDS = ['topic', 'audience', 'description', 'github_url', 'screenshot_file_id', 'special_instructions', 'post_mode', 'last_asked', 'intake_mode', 'status', 'status_at'];
const session = {};
for (const k of FIELDS) session[k] = row[k] == null ? '' : String(row[k]);

// Largest photo size, or an image sent as a file (keeps full resolution)
const photos = msg.photo || [];
let photoFileId = photos.length ? photos[photos.length - 1].file_id : '';
if (!photoFileId && msg.document && /^image\/(png|jpe?g)$/i.test(msg.document.mime_type || '')) {
  photoFileId = msg.document.file_id;
}

const text = String(msg.text || msg.caption || '').trim();
const age = Date.now() - Date.parse(session.status_at || 0);
// A generating run older than 25h is stale (the approval wait times out at 24h)
const busy = session.status === 'generating' && age < 25 * 3600 * 1000;

return [{ json: { session, text, photo_file_id: photoFileId, busy } }];

