const prep = $('Prepare Turn').first().json;
const out = $input.first().json.output || {};
const s = { ...prep.session };
const clean = (v) => (typeof v === 'string' ? v.trim() : '');
let intent = ['answer', 'greeting', 'reset', 'vague', 'skip'].includes(out.intent) ? out.intent : 'answer';

// Asked one at a time in this order; the last three are optional
const STEPS = ['topic', 'audience', 'description', 'github_url', 'screenshot', 'special_instructions'];
const REQUIRED = ['topic', 'audience', 'description'];
const QUESTIONS = {
  topic: "What's the topic of the post?",
  audience: "Who's the target audience?",
  description: "Give me a short description of what the post should cover. If it's about something you built, say what it does and what came out of it.",
  github_url: "Do you have a GitHub link to the n8n workflow (a .json file or a project folder)? I only use it to analyse the workflow; it won't appear in the post unless you ask.\n\nReply skip if not.",
  screenshot: "Want to add a workflow screenshot as the second image of the post? Send it as a photo or an image file.\n\nReply skip if not.",
  special_instructions: "Any special instructions? For example tone, length, hashtags, image style, or sharing the GitHub link in the post.\n\nReply skip if none.",
};
const filled = (k) => (k === 'screenshot' ? Boolean(s.screenshot_file_id) : Boolean(s[k]));
const notes = [];

if (intent === 'skip' && REQUIRED.includes(s.last_asked)) {
  notes.push('This one is required.');
  intent = 'vague';
}

if (intent === 'reset') {
  for (const k of ['topic', 'audience', 'description', 'github_url', 'screenshot_file_id', 'special_instructions', 'post_mode', 'intake_mode']) s[k] = '';
  s.last_asked = '';
} else {
  // Several details in the opening message = all-at-once mode: only missing required fields are asked, optional ones are skipped
  const given = ['topic', 'audience', 'description', 'github_url', 'special_instructions'].filter((k) => clean(out[k])).length + (prep.photo_file_id ? 1 : 0);
  if (given >= 2 && ['', 'topic'].includes(s.last_asked)) s.intake_mode = 'bulk';

  for (const k of REQUIRED) if (clean(out[k])) s[k] = clean(out[k]);

  const gh = clean(out.github_url);
  if (gh) {
    if (/^(https?:\/\/)?(www\.)?github\.com\/\S+/i.test(gh)) {
      s.github_url = /^https?:\/\//i.test(gh) ? gh : 'https://' + gh;
    } else {
      notes.push("That link isn't a github.com URL, so I skipped it.");
    }
  }

  const si = clean(out.special_instructions);
  if (si) s.special_instructions = s.special_instructions ? s.special_instructions + '\n' + si : si;

  if (out.post_mode === 'project' || out.post_mode === 'educational') s.post_mode = out.post_mode;

  if (prep.photo_file_id) {
    s.screenshot_file_id = prep.photo_file_id;
    notes.push('Screenshot saved. It will be the second image of the post.');
  }
  // A GitHub URL or a screenshot always means a project showcase
  if (s.github_url || s.screenshot_file_id) s.post_mode = 'project';
}

// Steps up to the last question count as answered (or skipped); a vague reply re-asks the same question
const lastIdx = s.last_asked === 'recap' ? STEPS.length : STEPS.indexOf(s.last_asked);
const progress = intent === 'vague' ? lastIdx - 1 : lastIdx;
const bulk = s.intake_mode === 'bulk';
const next = REQUIRED.find((k) => !filled(k))
  || (bulk ? undefined : STEPS.find((k, i) => !REQUIRED.includes(k) && i > progress && !filled(k)));

const WELCOME = "Hi! Let's create a LinkedIn post.\n\nSend everything in one message, or I'll ask one question at a time:\n- Topic\n- Target audience\n- Description\n- GitHub URL (optional)\n- Workflow screenshot (optional)\n- Special instructions (optional)";
const parts = [...notes];
let ready = false;

if (next) {
  if (intent === 'reset') parts.unshift("Let's start over.");
  if (intent === 'greeting') parts.unshift(WELCOME);
  if (intent === 'vague' && !parts.includes('This one is required.')) parts.push("I didn't catch that.");
  parts.push(QUESTIONS[next]);
  s.last_asked = next;
} else {
  if (!s.post_mode) s.post_mode = 'educational';
  ready = true;
  s.last_asked = 'recap';
  if (intent === 'vague') parts.push("I didn't catch that. Here's what I have so far.");
  parts.push([
    "Here's your post brief:",
    'Post type: ' + (s.post_mode === 'project' ? 'Project showcase' : 'Educational'),
    'Topic: ' + s.topic,
    'Target audience: ' + s.audience,
    'Description: ' + s.description,
    'GitHub URL: ' + (s.github_url || 'none'),
    'Screenshot: ' + (s.screenshot_file_id ? 'attached' : 'none'),
    'Special instructions: ' + (s.special_instructions || 'none'),
    bulk
      ? 'Type a correction, add a GitHub link, screenshot or special instructions, or tap Generate.'
      : 'Type a correction to change anything, or tap Generate.',
  ].join('\n\n'));
}

let reply = parts.join('\n\n');
if (reply.length > 4000) reply = reply.slice(0, 3990) + '...';

return [{ json: { session: s, reply, ready } }];
